    path = path.resolve()
    if not path.is_relative_to(self.root):
        raise ValueError("sha256_file path escapes the workspace")
    if not path.is_file():
        raise ValueError("sha256_file requires an existing ordinary file")
    size = path.stat().st_size
    if size > 1048576:
        raise ValueError("sha256_file rejects files larger than 1048576 bytes")
    with path.open("rb") as stream:
        sha256 = hashlib.sha256(stream.read()).hexdigest()
    return {"path": str(path.relative_to(self.root)), "bytes": size, "sha256": sha256}
